// TP : charge et décharge d'un condensateur (R = 10 kΩ, C = 100 µF).
const int CHARGE = 7;

void mesurer() {
  float u = analogRead(A0) * 5.0 / 1023;   // tension du condensateur, en volts
  Serial.print("tension:");
  Serial.println(u);
  delay(20);                                // une mesure toutes les 20 ms
}

void setup() {
  Serial.begin(9600);
  pinMode(CHARGE, OUTPUT);
}

void loop() {
  digitalWrite(CHARGE, HIGH);               // charge pendant 5 s
  for (int i = 0; i < 250; i++) mesurer();
  digitalWrite(CHARGE, LOW);                // décharge pendant 5 s
  for (int i = 0; i < 250; i++) mesurer();
}
